<main class="content"><div class="page-actions"><a href="<?=url($type==='test'?'/admin/tests':'/admin/tabuladores')?>">← Volver a <?=$type==='test'?'tests':'tabuladores'?></a></div><section class="panel form-page"><div class="panel-head"><div><span class="eyebrow"><?=$type==='test'?'MÓDULO DE TESTS':'MÓDULO DE TABULADORES'?></span><h2><?=$resource?'Editar':'Crear nuevo'?> <?=$type==='test'?'test':'tabulador'?></h2><p>Registra la información y adjunta un archivo o enlace externo.</p></div></div><form method="post" enctype="multipart/form-data" action="<?=url('/admin/recursos/guardar')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($resource['id']??'')?>"><input type="hidden" name="type" value="<?=$type?>"><div class="form-grid"><label class="wide">Nombre<input required name="name" value="<?=e($resource['name']??'')?>"></label><label class="wide">Descripción<textarea name="description" rows="5"><?=e($resource['description']??'')?></textarea></label><label>Asignatura<select name="subject_id"><option value="">Todas las asignaturas</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>" <?=($resource['subject_id']??null)==$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></label><?php if($type==='tabulador'):?><label>Grupo<select name="group_id"><option value="">Sin grupo</option><?php foreach($groups as $g):?><option value="<?=$g['id']?>" <?=($resource['group_id']??null)==$g['id']?'selected':''?>><?=e($g['name'])?></option><?php endforeach;?></select></label><label>Subgrupo<select name="subgroup_id"><option value="">Sin subgrupo</option><?php foreach($subgroups as $s):?><option value="<?=$s['id']?>" <?=($resource['subgroup_id']??null)==$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></label><?php else:?><input type="hidden" name="group_id" value=""><input type="hidden" name="subgroup_id" value=""><?php endif;?><label>Archivo<input type="file" name="file"><?php if(!empty($resource['file_path'])):?><small>Archivo actual: <?=e($resource['file_path'])?></small><?php endif;?></label><label class="wide">Enlace externo<input type="url" name="external_link" value="<?=e($resource['external_link']??'')?>" placeholder="https://..."></label><input type="hidden" name="active" value="0"><label class="check"><input type="checkbox" name="active" value="1" <?=!isset($resource['active'])||$resource['active']?'checked':''?>> Recurso activo y visible</label></div><div class="form-actions"><a class="secondary" href="<?=url($type==='test'?'/admin/tests':'/admin/tabuladores')?>">Cancelar</a><button class="primary">Guardar recurso</button></div></form></section></main>
